with paid_order as ( select order_id, customer_id, amount, payment_time from style_lab.fact_order where dt = '2026-08-19' and order_status in ('paid', 'shipped', 'completed') ), customer_summary as ( select customer_id, count(*) as order_count, sum(amount) as total_amount, max(payment_time) as latest_payment_time from paid_order group by customer_id ), ranked_customer as ( select customer_id, order_count, total_amount, latest_payment_time, row_number() over ( order by total_amount desc, customer_id ) as amount_rank from customer_summary ) select customer_id, order_count, total_amount, latest_payment_time, amount_rank from ranked_customer where amount_rank <= 100 order by amount_rank;
